import 'package:flutter/material.dart';
import '../data/mock_geo_repository.dart';
import '../domain/geo_models.dart';
enum ShopProductSort { lowestPrice, highestPrice, recentlyUpdated, inStock, offers }
class ShopDetailsScreen extends StatefulWidget{const ShopDetailsScreen({required this.shopId,super.key});final String shopId;@override State<ShopDetailsScreen> createState()=>_ShopDetailsScreenState();}
class _ShopDetailsScreenState extends State<ShopDetailsScreen>{ShopProductSort sort=ShopProductSort.lowestPrice;@override Widget build(BuildContext context){final shop=mockNearbyShops.where((s)=>s.id==widget.shopId).firstOrNull;if(shop==null)return const Scaffold(body:Center(child:Text('Shop unavailable')));return Scaffold(appBar:AppBar(title:Text(shop.name)),body:ListView(padding:const EdgeInsets.all(20),children:[Container(height:160,decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer,borderRadius:BorderRadius.circular(20)),child:const Icon(Icons.storefront,size:80)),const SizedBox(height:16),Text(shop.businessName,style:Theme.of(context).textTheme.headlineSmall),Text(shop.address),ListTile(contentPadding:EdgeInsets.zero,leading:Icon(shop.verified?Icons.verified:Icons.info),title:Text(shop.verified?'Verified shop':'Verification pending'),subtitle:Text('Trust score ${shop.trustScore} · Open 9:00 AM–9:00 PM\nContact placeholder')),const Divider(),Text('Available categories',style:Theme.of(context).textTheme.titleMedium),Wrap(spacing:8,children:[Chip(label:Text(shop.category)),const Chip(label:Text('Groceries')),const Chip(label:Text('Household'))]),ListTile(contentPadding:EdgeInsets.zero,title:const Text('Active offers'),subtitle:Text('${shop.activeOffers} offers · Prices refreshed today')),DropdownButtonFormField(value:sort,decoration:const InputDecoration(labelText:'Sort products'),items:ShopProductSort.values.map((v)=>DropdownMenuItem(value:v,child:Text(_label(v)))).toList(),onChanged:(v)=>setState(()=>sort=v!)),...List.generate(5,(i)=>ListTile(leading:const CircleAvatar(child:Icon(Icons.shopping_bag_outlined)),title:Text('Mock product ${i+1}'),subtitle:Text(i%2==0?'In stock · Updated today':'Low stock · Updated yesterday'),trailing:Text('₹${99+i*45}')))]));}String _label(ShopProductSort v)=>switch(v){ShopProductSort.lowestPrice=>'Lowest price',ShopProductSort.highestPrice=>'Highest price',ShopProductSort.recentlyUpdated=>'Recently updated',ShopProductSort.inStock=>'In stock',ShopProductSort.offers=>'Offers'};}
